-- ===== 5s: team, settings, photo bucket =====

-- ใครทำอะไรในปีนี้ ที่เดียว: admin = ดูแล Setting (CFO: ผู้จัดทำ), chairman = ประธาน / หัวหน้าทีมตรวจ, vice = รองประธาน,
-- auditor = ผู้ตรวจในทีม A–Z, owner = เจ้าของพื้นที่ (area_id) ปีละ 1 คนต่อพื้นที่,
-- member = ตัวแทนหน่วยงาน (department) 1 คนดูแลได้หลายหน่วยงาน
create table if not exists public.mt_5s_team (
  id bigint generated by default as identity primary key,
  year integer not null check (year between 2000 and 2100),
  employee_id text not null,
  role text not null,
  team text check (team ~ '^[A-Z]$'),
  area_id bigint,
  department text,
  status text not null default 'Active' check (status in ('Active', 'Inactive')),
  constraint mt_5s_team_auditor_has_team check ((role = 'auditor') = (team is not null)),
  constraint mt_5s_team_owner_has_area check ((role = 'owner') = (area_id is not null))
);
alter table public.mt_5s_team add column if not exists department text;
-- unit = ทีมย่อยของกิจกรรม (ผู้ใช้กำหนด 2026-10-30) · ว่าง = คณะกรรมการกลาง (ประธาน · รองประธาน · ที่ปรึกษา · ผู้ประสานงาน)
-- 5S: standard ทีมมาตรฐาน · academic ทีมวิชาการ · pr ทีมประชาสัมพันธ์ · audit ทีมตรวจประเมิน (+ ผู้รับผิดชอบพื้นที่ / ผู้ตรวจ) · server ตรวจค่า
alter table public.mt_5s_team add column if not exists unit text;
alter table public.mt_5s_team
  drop constraint if exists mt_5s_team_role_check,
  drop constraint if exists mt_5s_team_member_has_dept,
  drop constraint if exists mt_5s_team_unique;
-- ร่างเดิมเก็บชื่อทีมย่อยเป็นบทบาท: ย้ายเป็นสมาชิกของทีมนั้น (รันซ้ำได้)
update public.mt_5s_team set unit = role, role = 'member' where role in ('standard', 'academic', 'pr');
alter table public.mt_5s_team
  add constraint mt_5s_team_role_check check (role in ('admin', 'chairman', 'vice', 'advisor', 'smart', 'auditor', 'owner', 'member')),
  -- สมาชิก = ตัวแทนหน่วยงาน (department) หรือสมาชิกของทีมย่อย (unit) · บทบาทอื่นไม่มีหน่วยงาน
  add constraint mt_5s_team_member_has_dept check (case when role = 'member' then department is not null or unit is not null else department is null end),
  add constraint mt_5s_team_unique unique nulls not distinct (year, employee_id, role, unit, team, area_id, department);
create index if not exists mt_5s_team_lookup on public.mt_5s_team (year, employee_id);
create unique index if not exists mt_5s_team_one_owner on public.mt_5s_team (year, area_id) where role = 'owner';

create table if not exists public.mt_5s_setting (
  key text primary key,
  value text not null
);

-- ที่เก็บรูปของกิจกรรมนี้ (Supabase Storage) ชื่อ img_5s · รูป JPEG ≤ 700 KB เปิดดูได้ด้วยลิงก์
-- ข้ามไปเองถ้าฐานไม่มี storage (เช่นตอนทดสอบด้วย PGlite)
do $$ begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('img_5s', 'img_5s', true, 716800, array['image/jpeg'])
    on conflict (id) do nothing;
  end if;
end $$;

-- ===== 5s: Project Planner =====

-- ข้อหลัก (parent_id ว่าง) และข้อรอง (parent_id = ข้อหลัก) ลึก 2 ระดับ (server ตรวจ) · ลบข้อหลักแล้วข้อรองหายด้วย
-- ข้อหลักที่มีข้อรอง: ช่วงวันและ % คิดจากข้อรอง (server) ค่าที่เก็บในแถวข้อหลักไม่ใช้
create table if not exists public.mt_5s_task (
  id bigint generated by default as identity primary key,
  year integer not null check (year between 2000 and 2100),
  parent_id bigint references public.mt_5s_task (id) on delete cascade,
  sort_no integer not null default 1,
  title text not null,
  start_date date,
  end_date date,
  progress integer not null default 0 check (progress between 0 and 100),
  owner_id text,                                          -- employee_id (Mx Data)
  color text,                                             -- สีของข้อหลัก p1–p12
  note text,
  created_by text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint mt_5s_task_dates check ((start_date is null) = (end_date is null) and end_date >= start_date),
  constraint mt_5s_task_sub_has_dates check (parent_id is null or start_date is not null)
);
create index if not exists mt_5s_task_year on public.mt_5s_task (year, parent_id, sort_no);
-- วันที่ทำครบ 100% (server ใส่ให้) ใช้บอกเสร็จก่อนแผน / ตามแผน / ช้า เทียบกับ end_date · เพิ่มทีหลัง จึงใช้ add column (รันซ้ำได้)
alter table public.mt_5s_task add column if not exists done_on date;
-- โครงการ / ทีมย่อยของข้อหลัก (SMF: mt_smf_project.code) · ข้อรองตามข้อหลัก (ผู้ใช้กำหนด 2026-11-01)
alter table public.mt_5s_task add column if not exists unit text;

-- ===== 5s: checklist audit =====

create table if not exists public.mt_5s_area (
  id bigint generated by default as identity primary key,
  code text not null unique,                              -- เช่น A01
  area_type text not null check (area_type in ('โรงงาน', 'สำนักงาน')),
  name text not null,
  section text,
  status text not null default 'Active' check (status in ('Active', 'Inactive'))
);

-- เจ้าของพื้นที่อยู่ใน mt_5s_team (role owner) ผูก area_id กับพื้นที่ที่นี่
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'mt_5s_team_area_fk') then
    alter table public.mt_5s_team add constraint mt_5s_team_area_fk foreign key (area_id) references public.mt_5s_area (id) on delete cascade;
  end if;
end $$;

-- หัวข้อตรวจรายปี (5S: 25 ข้อ, s_group 1–5)
create table if not exists public.mt_5s_checklist (
  id bigint generated by default as identity primary key,
  year integer not null check (year between 2000 and 2100),
  item_no integer not null check (item_no between 1 and 200),
  s_group integer not null check (s_group between 1 and 20),
  title text not null,
  score_max integer not null default 5 check (score_max > 0),
  status text not null default 'Active' check (status in ('Active', 'Inactive')),
  unique (year, item_no)
);


-- แผนตรวจ Committee: พื้นที่ × เดือน × สัปดาห์ (W1 = 1–7, W2 = 8–14, W3 = 15–21, W4 = 22–สิ้นเดือน)
create table if not exists public.mt_5s_audit_plan (
  id bigint generated by default as identity primary key,
  year integer not null check (year between 2000 and 2100),
  area_id bigint not null references public.mt_5s_area (id) on delete cascade,
  month integer not null check (month between 1 and 12),
  week integer not null check (week between 1 and 4),
  round integer check (round between 1 and 6),
  team text check (team ~ '^[A-Z]$'),
  created_at timestamptz not null default now(),
  unique (year, area_id, month, week)
);

insert into public.mt_5s_setting (key, value) values
  ('pass_percent', '80'),                -- ผ่านเมื่อ % ≥ 80
  ('issue_score', '3'),                  -- Committee: ข้อที่ได้ต่ำกว่า 3 ต้องเปิด Issue (รูป 16:9 + รายละเอียด)
  ('issue_due_days_before_next', '15'),  -- ผู้รับผิดชอบพื้นที่ Action ให้เสร็จก่อนตรวจรอบถัดไป 15 วัน
  ('issue_photo_max', '1'),              -- รูปปัญหา 16:9 1 รูป
  ('self_audit_due_day', '10')           -- Self Audit ภายในวันที่ 10 ของเดือน
on conflict (key) do nothing;
-- ผู้ใช้กำหนด 2026-10-30: Action ก่อนตรวจรอบถัดไป 15 วัน (เดิม 10) · ฐานที่ยังเป็นค่าเดิมเปลี่ยนตาม (ค่าที่ตั้งเองไม่แตะ)
update public.mt_5s_setting set value = '15' where key = 'issue_due_days_before_next' and value = '10';

create table if not exists public.tx_5s_audit (
  id bigint generated by default as identity primary key,
  audit_no text not null unique,                          -- C|S-<area>-<ddMMyy>-<seq> เช่น C-A01-040926-01
  year integer not null check (year between 2000 and 2100),
  audit_type text not null check (audit_type in ('SELF', 'COMMITTEE')),
  area_id bigint not null references public.mt_5s_area (id),
  plan_id bigint references public.mt_5s_audit_plan (id) on delete set null,
  team text,
  auditors text[] not null default '{}',                  -- ผู้ตรวจที่ไปตรวจจริง (employee_id)
  receivers text[] not null default '{}',                 -- ผู้รับตรวจในพื้นที่ (employee_id)
  audited_at timestamptz not null,
  total_score numeric(8, 2) not null default 0,
  percent_score numeric(5, 2) not null default 0,
  result text check (result in ('PASS', 'NEED_IMPROVE')),
  status text not null default 'DRAFT' check (status in ('DRAFT', 'COMPLETED')),
  created_by text,
  created_at timestamptz not null default now()
);
create index if not exists tx_5s_audit_lookup on public.tx_5s_audit (year, area_id, audited_at);

create table if not exists public.tx_5s_audit_score (
  audit_id bigint not null references public.tx_5s_audit (id) on delete cascade,
  checklist_id bigint not null references public.mt_5s_checklist (id),
  score numeric(5, 2) not null check (score >= 0),       -- 0 = Issue เดิมไม่มี Action
  primary key (audit_id, checklist_id)
);

create table if not exists public.tx_5s_issue (
  id bigint generated by default as identity primary key,
  issue_no text not null unique,                          -- ISS0001
  audit_id bigint not null references public.tx_5s_audit (id) on delete cascade,
  area_id bigint not null references public.mt_5s_area (id),
  checklist_id bigint not null references public.mt_5s_checklist (id),
  score numeric(5, 2) not null,
  description text not null,
  photo_before text[] not null default '{}',              -- ลิงก์รูปปัญหา (16:9)
  photo_after text[] not null default '{}',               -- ลิงก์รูปหลังแก้
  issue_date date not null,
  responsible_id text,
  due_date date,                                          -- null = รอกำหนดรอบถัดไป
  action_description text,
  action_date date,
  status text not null default 'OPEN' check (status in ('OPEN', 'ON_PLAN', 'WAIT_VERIFY', 'OVERDUE', 'CLOSED')),
  verify_audit_no text,                                   -- ใบตรวจรอบถัดไปที่ยืนยันผล (ข้อมูลเดิมบางใบไม่มีในระบบ จึงเก็บเป็นเลข)
  final_score numeric(5, 2),
  closed_by text,
  closed_at date
);
create index if not exists tx_5s_issue_area on public.tx_5s_issue (area_id, status);

-- % ของแต่ละหมวดต่อใบตรวจ (Summary / Ranking) · security_invoker = ใช้สิทธิ์ของคนเรียก ไม่ข้าม RLS
create or replace view public.v_5s_audit_group with (security_invoker = true) as
select s.audit_id, c.s_group,
  sum(s.score) as score,
  sum(c.score_max) as score_max,
  round(sum(s.score) * 100.0 / nullif(sum(c.score_max), 0), 2) as percent
from public.tx_5s_audit_score s
join public.mt_5s_checklist c on c.id = s.checklist_id
group by s.audit_id, c.s_group;

-- server ใช้ service key ซึ่งข้าม RLS ได้ เปิด RLS ไว้กันการเข้าถึงด้วย anon key
alter table public.mt_5s_team enable row level security;
alter table public.mt_5s_setting enable row level security;
alter table public.mt_5s_task enable row level security;
alter table public.mt_5s_area enable row level security;
alter table public.mt_5s_checklist enable row level security;
alter table public.mt_5s_audit_plan enable row level security;
alter table public.tx_5s_audit enable row level security;
alter table public.tx_5s_audit_score enable row level security;
alter table public.tx_5s_issue enable row level security;

notify pgrst, 'reload schema';

